35	IProcessor::Status OffsetTransform::prepare(const PortNumbers & updated_input_ports, const PortNumbers & updated_output_ports)
36	{
37	    bool has_full_port = false;
38	
39	    auto process_pair = [&](size_t pos)
40	    {
41	        auto status = preparePair(ports_data[pos]);
42	
43	        switch (status)
44	        {
45	            case IProcessor::Status::Finished:
46	            {
47	                if (!ports_data[pos].is_finished)
48	                {
49	                    ports_data[pos].is_finished = true;
50	                    ++num_finished_port_pairs;
51	                }
52	
53	                return;
54	            }
55	            case IProcessor::Status::PortFull:
56	            {
57	                has_full_port = true;
58	                return;
59	            }
60	            case IProcessor::Status::NeedData:
61	                return;
62	            default:
63	                throw Exception(
64	                    ErrorCodes::LOGICAL_ERROR, "Unexpected status for OffsetTransform::preparePair : {}", IProcessor::statusToName(status));
65	        }
66	    };
67	
68	    for (auto pos : updated_input_ports)
69	        process_pair(pos);
70	
71	    for (auto pos : updated_output_ports)
72	        process_pair(pos);
73	
74	    /// All ports are finished. It may happen even before we reached the limit (has less data then limit).
75	    if (num_finished_port_pairs == ports_data.size())
76	        return Status::Finished;
77	
