93	OffsetTransform::Status OffsetTransform::preparePair(PortsData & data)
94	{
95	    auto & output = *data.output_port;
96	    auto & input = *data.input_port;
97	
98	    /// Check can output.
99	    bool output_finished = false;
100	    if (output.isFinished())
101	    {
102	        output_finished = true;
103	    }
104	
105	    if (!output_finished && !output.canPush())
106	    {
107	        input.setNotNeeded();
108	        return Status::PortFull;
109	    }
110	
111	    /// Check can input.
112	
113	    if (input.isFinished())
114	    {
115	        output.finish();
116	        return Status::Finished;
117	    }
118	
119	    input.setNeeded();
120	    if (!input.hasData())
121	        return Status::NeedData;
122	
123	    data.current_chunk = input.pull(true);
124	
125	    auto rows = data.current_chunk.getNumRows();
126	
127	    if (rows_before_limit_at_least)
128	        rows_before_limit_at_least->add(rows);
129	
130	    /// Process block.
131	
132	    rows_read += rows;
133	
134	    if (rows_read <= offset)
135	    {
136	        data.current_chunk.clear();
137	
138	        if (input.isFinished())
139	        {
140	            output.finish();
141	            return Status::Finished;
142	        }
143	
144	        /// Now, we pulled from input, and it must be empty.
145	        input.setNeeded();
146	        return Status::NeedData;
147	    }
148	
149	    if (!(rows <= std::numeric_limits<UInt64>::max() - offset && rows_read >= offset + rows))
150	        splitChunk(data);
151	
152	    output.push(std::move(data.current_chunk));
153	
154	    return Status::PortFull;
155	}
156	
157	
158	void OffsetTransform::splitChunk(PortsData & data) const
159	{
160	    UInt64 num_rows = data.current_chunk.getNumRows();
161	    UInt64 num_columns = data.current_chunk.getNumColumns();
162	
163	    /// return a piece of the block
164	    UInt64 start = 0;
165	
166	    /// ------------[....(.....]
167	    /// <----------------------> rows_read
168	    ///             <----------> num_rows
169	    /// <---------------> offset
170	    ///             <---> start
171	
172	    assert(offset < rows_read);
173	
174	    if (offset + num_rows > rows_read)
175	        start = offset + num_rows - rows_read;
176	    else
177	        return;
178	
179	    UInt64 length = num_rows - start;
180	
181	    auto columns = data.current_chunk.detachColumns();
182	
183	    for (UInt64 i = 0; i < num_columns; ++i)
184	        columns[i] = columns[i]->cut(start, length);
185	
186	    data.current_chunk.setColumns(std::move(columns), length);
187	}
